    @ConfigSection(
        name = "Inventory Value",
        description = "Display inventory value overlay",
        position = 4
    )
    String inventoryValueSection = "inventoryValue";

    @ConfigSection(
        name = "Music",
        description = "Music track now-playing overlay",
        position = 5
    )
    String musicSection = "music";

    @ConfigSection(
        name = "Bank Highlight",
        description = "Highlight hovered item slots in the bank",
        position = 6
    )
    String bankHighlightSection = "bankHighlight";

    // ---- Transparency ----

    @ConfigItem(
        keyName = "hideGEBackground",
        name = "GE Transparency",
        description = "Enable transparency for the Grand Exchange background",
        position = 0,
        section = transparencySection
    )
    default boolean hideGEBackground()
    {
        return false;
    }

    @Range(min = 0, max = 255)
    @ConfigItem(
        keyName = "geTransparencyLevel",
        name = "GE Transparency Level",
        description = "How transparent the Grand Exchange background should be (0 = opaque, 255 = invisible)",
        position = 1,
        section = transparencySection
    )
    default int geTransparencyLevel()
    {
        return 200;
    }

    @ConfigItem(
        keyName = "hideBankBackground",
        name = "Bank Transparency",
        description = "Enable transparency for the Bank background",
        position = 2,
        section = transparencySection
    )
    default boolean hideBankBackground()
    {
        return false;
    }

    @Range(min = 0, max = 255)
    @ConfigItem(
        keyName = "bankTransparencyLevel",
        name = "Bank Transparency Level",
        description = "How transparent the Bank background should be (0 = opaque, 255 = invisible)",
        position = 3,
        section = transparencySection
    )
    default int bankTransparencyLevel()
    {
        return 200;
    }

    @ConfigItem(
        keyName = "hideShopBackground",
        name = "Shop Transparency",
        description = "Enable transparency for the Shop background",
        position = 4,
        section = transparencySection
    )
    default boolean hideShopBackground()
