        return false;
    }

    @Range(min = 0, max = 255)
    @ConfigItem(
        keyName = "shopTransparencyLevel",
        name = "Shop Transparency Level",
        description = "How transparent the Shop background should be (0 = opaque, 255 = invisible)",
        position = 5,
        section = transparencySection
    )
