    @Range(min = 0, max = 255)
    @ConfigItem(
        keyName = "bankHoverHighlightAlpha",
        name = "Fill Alpha",
        description = "Opacity of the fill behind the highlighted slot (0 = no fill, 255 = fully opaque)",
        position = 2,
        section = bankHighlightSection
    )
    default int bankHoverHighlightAlpha()
    {
        return 30;
