package com.transparentui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

public class MusicTrackOverlay extends Overlay
{
    private static final int MUSIC_PLAYER_GROUP = 239;
    private static final int MUSIC_TRACK_NAME_CHILD = 4;

    private static final long DISPLAY_DURATION_MS = 5_000;
    private static final long PROGRESS_CYCLE_MS = 30_000;

    private static final int CARD_WIDTH = 220;
    private static final int CARD_HEIGHT = 62;
    private static final int PADDING = 10;
    private static final int BAR_HEIGHT = 4;

    private static final Color BG_COLOR = new Color(10, 10, 10, 230);
    private static final Color ACCENT_COLOR = new Color(255, 215, 0);
    private static final Color SHADOW_COLOR = new Color(0, 0, 0, 180);
    private static final Color TEXT_COLOR = Color.WHITE;
    private static final Color BAR_BG_COLOR = new Color(50, 50, 50);

    private final Client client;
    private final TransparentInterfacesConfig config;

    private String currentTrack = null;
    private long trackStartTime = -1;
    private String lastPolledName = null;

    private Font cachedBaseFont;
    private Font labelFont;
    private Font trackFont;

    @Inject
    public MusicTrackOverlay(Client client, TransparentInterfacesConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.BOTTOM_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    public void checkForTrackChange()
    {
        Widget nameWidget = client.getWidget(MUSIC_PLAYER_GROUP, MUSIC_TRACK_NAME_CHILD);
        if (nameWidget == null || nameWidget.isHidden())
        {
            return;
        }

        String raw = nameWidget.getText();
        if (raw == null)
        {
            return;
        }

        String name = Text.removeTags(raw).trim();
        if (name.isEmpty() || name.equals(lastPolledName))
        {
            return;
        }

        lastPolledName = name;
        currentTrack = name;
        trackStartTime = System.currentTimeMillis();
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showMusicTrack() || currentTrack == null || trackStartTime < 0)
        {
            return null;
        }

        long elapsed = System.currentTimeMillis() - trackStartTime;
        if (config.musicTrackAutoHide() && elapsed > DISPLAY_DURATION_MS)
        {
            return null;
        }

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // Background
        graphics.setColor(BG_COLOR);
        graphics.fillRoundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 10, 10);

        // "♪ NOW PLAYING" label
        Font baseFont = graphics.getFont();
        if (baseFont != cachedBaseFont)
        {
            cachedBaseFont = baseFont;
            labelFont = baseFont.deriveFont(Font.BOLD, 10f);
            trackFont = baseFont.deriveFont(Font.BOLD, 13f);
        }
        graphics.setFont(labelFont);
        graphics.setColor(SHADOW_COLOR);
        graphics.drawString("♪ NOW PLAYING", PADDING + 1, PADDING + 11);
        graphics.setColor(ACCENT_COLOR);
        graphics.drawString("♪ NOW PLAYING", PADDING, PADDING + 10);

        // Track name — larger, bold, with shadow
        graphics.setFont(trackFont);
        String display = truncate(graphics, currentTrack, CARD_WIDTH - PADDING * 2);
        graphics.setColor(SHADOW_COLOR);
        graphics.drawString(display, PADDING + 1, PADDING + 29);
        graphics.setColor(TEXT_COLOR);
        graphics.drawString(display, PADDING, PADDING + 28);

        // Progress bar
        int barY = CARD_HEIGHT - PADDING - BAR_HEIGHT;
        int barWidth = CARD_WIDTH - PADDING * 2;
        double progress = (double) (elapsed % PROGRESS_CYCLE_MS) / PROGRESS_CYCLE_MS;

        graphics.setColor(BAR_BG_COLOR);
        graphics.fillRoundRect(PADDING, barY, barWidth, BAR_HEIGHT, 2, 2);
        graphics.setColor(ACCENT_COLOR);
        graphics.fillRoundRect(PADDING, barY, (int) (barWidth * progress), BAR_HEIGHT, 2, 2);

        return new Dimension(CARD_WIDTH, CARD_HEIGHT);
    }

    private String truncate(Graphics2D graphics, String text, int maxWidth)
    {
        FontMetrics fm = graphics.getFontMetrics();
        if (fm.stringWidth(text) <= maxWidth)
        {
            return text;
        }
        while (text.length() > 1 && fm.stringWidth(text + "...") > maxWidth)
        {
            text = text.substring(0, text.length() - 1);
        }
        return text + "...";
    }
}

