package com.transparentui;

import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;

public class ShopOverlay extends MoveableInterfaceOverlay
{
    static final int SHOP_INTERFACE_ID = 300;
    private static final int TITLE_BAR_HEIGHT = 28;
    private static final int CLOSE_BUTTON_WIDTH = 30;
    private static final int LEFT_MARGIN = 10;

    @Inject
    public ShopOverlay(Client client, TransparentInterfacesConfig config, ConfigManager configManager)
    {
        super(client, config, configManager);
    }

    @Override
    protected String getPositionConfigKey()
    {
        return "shop";
    }

    @Override
    protected boolean isFeatureEnabled()
    {
        return config.moveableShop();
    }

    @Override
    protected Widget getInterfaceWindow()
    {
        return client.getWidget(SHOP_INTERFACE_ID, 0);
    }

    @Override
    protected Rectangle getTitleBarDragRegion(Widget interfaceWindow)
    {
        Rectangle bounds = interfaceWindow.getBounds();
        if (bounds == null)
        {
            return null;
        }

        return new Rectangle(
            bounds.x + LEFT_MARGIN,
            bounds.y,
            bounds.width - LEFT_MARGIN - CLOSE_BUTTON_WIDTH,
            TITLE_BAR_HEIGHT
        );
    }
}

