@Slf4j
@PluginDescriptor(
    name = "QOL Interfaces",
    description = "Quality of life improvements for game interfaces - transparency, repositioning, and more",
    tags = {"interface", "transparency", "ui", "grand exchange", "bank", "qol", "moveable", "collection log", "music"}
)
public class TransparentInterfacesPlugin extends Plugin
{
    public static final String CONFIG_GROUP = "transparentinterfaces";

    private static final String UNLOCK_HINT_OPTION = "Unlock Hint";

    // Widget IDs
    private static final int GE_INTERFACE_ID = InterfaceID.GRAND_EXCHANGE;
    private static final int GE_BACKGROUND_CHILD_ID = 2;
    private static final int BANK_INTERFACE_ID = InterfaceID.BANK;
    private static final int BANK_BACKGROUND_CHILD_ID = 2;
    private static final int SHOP_INTERFACE_ID = ShopOverlay.SHOP_INTERFACE_ID;
    private static final int SHOP_BACKGROUND_CHILD_ID = 1;

    // Collection Log
    private static final int COLLECTION_LOG_GROUP = 621;
    private static final int COLLECTION_LOG_ITEMS_CONTAINER = 37;

    private static final int OPACITY_OPAQUE = 0;

    private static final Set<String> TRANSPARENCY_KEYS = ImmutableSet.of(
        "hideGEBackground", "geTransparencyLevel", "hideBankBackground", "bankTransparencyLevel",
        "hideShopBackground", "shopTransparencyLevel"
    );

    @Inject
    private Client client;

    @Inject
    private TransparentInterfacesConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private ClientThread clientThread;

    @Inject
    private GrandExchangeOverlay geOverlay;

    @Inject
    private BankOverlay bankOverlay;

    @Inject
    private TradeOverlay tradeOverlay;

    @Inject
    private InventoryValueOverlay inventoryValueOverlay;

    @Inject
    private ShopOverlay shopOverlay;

    @Inject
    private MusicTrackOverlay musicTrackOverlay;

    @Inject
    private BankHoverOverlay bankHoverOverlay;

    private boolean collectionLogFilterApplied;
    private int[] collectionLogStoredIds;
    private int[] collectionLogStoredRelX;
    private int[] collectionLogStoredRelY;
    private int clGridStartX;
    private int clGridStartY;
    private int clGridXStep = 36;
    private int clGridYStep = 36;
    private int clGridNumCols = 8;

    @Override
    protected void startUp() throws Exception
    {
        log.debug("QOL Interfaces started!");
        overlayManager.add(geOverlay);
        overlayManager.add(bankOverlay);
        overlayManager.add(shopOverlay);
        overlayManager.add(tradeOverlay);
        overlayManager.add(inventoryValueOverlay);
        overlayManager.add(musicTrackOverlay);
        overlayManager.add(bankHoverOverlay);
        mouseManager.registerMouseListener(geOverlay);
        mouseManager.registerMouseListener(bankOverlay);
        mouseManager.registerMouseListener(shopOverlay);
        // Apply transparency on client thread
        clientThread.invokeLater(this::applyTransparencySettings);
    }

    @Override
    protected void shutDown() throws Exception
    {
        log.debug("QOL Interfaces stopped!");
        mouseManager.unregisterMouseListener(geOverlay);
        mouseManager.unregisterMouseListener(bankOverlay);
        mouseManager.unregisterMouseListener(shopOverlay);
        overlayManager.remove(geOverlay);
        overlayManager.remove(bankOverlay);
        overlayManager.remove(shopOverlay);
        overlayManager.remove(tradeOverlay);
        overlayManager.remove(inventoryValueOverlay);
        overlayManager.remove(musicTrackOverlay);
        overlayManager.remove(bankHoverOverlay);
        geOverlay.resetPosition();
        bankOverlay.resetPosition();
        shopOverlay.resetPosition();
        // Must run on client thread for widget revalidation
        clientThread.invokeLater(this::resetAllTransparency);
        if (collectionLogFilterApplied)
        {
            clientThread.invokeLater(this::restoreCollectionLog);
        }
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        if (config.moveableGE())
        {
            geOverlay.onBeforeRender();
        }
        if (config.moveableBank())
        {
            bankOverlay.onBeforeRender();
        }
        if (config.moveableShop())
        {
            shopOverlay.onBeforeRender();
        }
        if (config.showMusicTrack())
        {
            musicTrackOverlay.checkForTrackChange();
        }
        if (config.hideObtainedItems() || collectionLogFilterApplied)
        {
            updateCollectionLogFilter();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        int groupId = event.getGroupId();
        if (groupId == GE_INTERFACE_ID)
        {
            geOverlay.onInterfaceLoaded();
            applyTransparencySettings();
        }
        else if (groupId == BANK_INTERFACE_ID)
        {
            bankOverlay.onInterfaceLoaded();
            applyTransparencySettings();
        }
        else if (groupId == SHOP_INTERFACE_ID)
        {
            shopOverlay.onInterfaceLoaded();
            applyTransparencySettings();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals(CONFIG_GROUP))
        {
            return;
        }

        String key = event.getKey();

        if (TRANSPARENCY_KEYS.contains(key))
        {
            clientThread.invokeLater(this::applyTransparencySettings);
        }

        // Clear saved position when a moveable feature is disabled (covers Reset and manual toggle-off)
        if ("moveableGE".equals(key) && !config.moveableGE())
        {
            geOverlay.clearSavedPosition();
        }
        else if ("moveableBank".equals(key) && !config.moveableBank())
        {
            bankOverlay.clearSavedPosition();
        }
        else if ("moveableShop".equals(key) && !config.moveableShop())
        {
            shopOverlay.clearSavedPosition();
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.INVENTORY.getId())
        {
            inventoryValueOverlay.refresh();
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        // Collection log hints
        if (config.collectionLogHints())
        {
            int groupId = event.getActionParam1() >> 16;
            int childId = event.getActionParam1() & 0xFFFF;

            if (groupId == COLLECTION_LOG_GROUP && childId == COLLECTION_LOG_ITEMS_CONTAINER)
            {
                int itemIndex = event.getActionParam0();
                Widget itemContainer = client.getWidget(COLLECTION_LOG_GROUP, COLLECTION_LOG_ITEMS_CONTAINER);
                if (itemContainer != null)
                {
                    Widget[] children = itemContainer.getDynamicChildren();
                    if (children != null && itemIndex >= 0 && itemIndex < children.length)
                    {
                        int itemId = children[itemIndex].getItemId();
                        if (CollectionLogHints.hasHint(itemId))
                        {
                            client.getMenu().createMenuEntry(-1)
                                .setOption(UNLOCK_HINT_OPTION)
                                .setTarget(event.getTarget())
                                .setType(MenuAction.RUNELITE)
                                .setIdentifier(itemId)
                                .setParam0(event.getActionParam0())
                                .setParam1(event.getActionParam1());
                        }
                    }
                }
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (event.getMenuOption().equals(UNLOCK_HINT_OPTION))
        {
            int itemId = event.getId();
            String hint = CollectionLogHints.getHint(itemId);

            if (hint != null)
            {
                String itemName = Text.removeTags(event.getMenuTarget());
                client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "<col=000000>" + itemName + "</col>: <col=ff0000>" + hint + "</col>",
                    null
                );
            }
        }
    }

    private void applyTransparencySettings()
    {
        setBackgroundOpacity(GE_INTERFACE_ID, GE_BACKGROUND_CHILD_ID,
            config.hideGEBackground() ? config.geTransparencyLevel() : OPACITY_OPAQUE);
        setBackgroundOpacity(BANK_INTERFACE_ID, BANK_BACKGROUND_CHILD_ID,
            config.hideBankBackground() ? config.bankTransparencyLevel() : OPACITY_OPAQUE);
        setBackgroundOpacity(SHOP_INTERFACE_ID, SHOP_BACKGROUND_CHILD_ID,
            config.hideShopBackground() ? config.shopTransparencyLevel() : OPACITY_OPAQUE);
    }

    private void resetAllTransparency()
    {
        setBackgroundOpacity(GE_INTERFACE_ID, GE_BACKGROUND_CHILD_ID, OPACITY_OPAQUE);
        setBackgroundOpacity(BANK_INTERFACE_ID, BANK_BACKGROUND_CHILD_ID, OPACITY_OPAQUE);
        setBackgroundOpacity(SHOP_INTERFACE_ID, SHOP_BACKGROUND_CHILD_ID, OPACITY_OPAQUE);
    }

    private void setBackgroundOpacity(int interfaceId, int childId, int opacity)
    {
        Widget frame = client.getWidget(interfaceId, childId);
        if (frame == null)
        {
            return;
        }

        Widget[] children = frame.getDynamicChildren();
        if (children == null || children.length == 0)
        {
            return;
        }

        Widget background = children[0];
        if (background != null)
        {
            background.setOpacity(opacity);
            background.revalidate();
        }
    }

    private void updateCollectionLogFilter()
    {
        Widget itemContainer = client.getWidget(COLLECTION_LOG_GROUP, COLLECTION_LOG_ITEMS_CONTAINER);
        if (itemContainer == null)
        {
            collectionLogFilterApplied = false;
            collectionLogStoredIds = null;
            return;
        }

        Widget[] children = itemContainer.getDynamicChildren();
        if (children == null)
        {
            return;
        }

        boolean shouldHide = config.hideObtainedItems();

        if (shouldHide)
        {
            if (!categoryMatchesStored(children))
            {
                storeCollectionLogPositions(children);
            }
            applyCollectionLogFilterAndCompact(children);
        }
        else if (collectionLogFilterApplied)
        {
            restoreCollectionLogPositions(children);
        }

        collectionLogFilterApplied = shouldHide;
    }

    private boolean categoryMatchesStored(Widget[] children)
    {
        if (collectionLogStoredIds == null || collectionLogStoredIds.length != children.length)
        {
            return false;
        }
        int checkCount = Math.min(5, children.length);
        for (int i = 0; i < checkCount; i++)
        {
            int id = children[i] != null ? children[i].getItemId() : -1;
            if (id != collectionLogStoredIds[i])
            {
                return false;
            }
        }
        return true;
    }

    private void storeCollectionLogPositions(Widget[] children)
    {
        collectionLogStoredIds = new int[children.length];
        collectionLogStoredRelX = new int[children.length];
        collectionLogStoredRelY = new int[children.length];
        for (int i = 0; i < children.length; i++)
        {
            Widget child = children[i];
            collectionLogStoredIds[i] = child != null ? child.getItemId() : -1;
            if (child != null)
            {
                collectionLogStoredRelX[i] = child.getRelativeX();
                collectionLogStoredRelY[i] = child.getRelativeY();
            }
        }
        computeGridParams(children);
    }

    private void computeGridParams(Widget[] children)
    {
        clGridStartX = 0;
        clGridStartY = 0;
        clGridXStep = 36;
        clGridYStep = 36;
        clGridNumCols = 8;

        int minY = Integer.MAX_VALUE;
        for (int i = 0; i < children.length; i++)
        {
            if (children[i] != null && children[i].getItemId() > 0)
            {
                int y = collectionLogStoredRelY[i];
                if (y < minY) minY = y;
            }
        }
        if (minY == Integer.MAX_VALUE)
        {
            return;
        }
        clGridStartY = minY;

        int[] firstRowXs = new int[children.length];
        int firstRowCount = 0;
        for (int i = 0; i < children.length; i++)
        {
            if (children[i] != null && children[i].getItemId() > 0 && collectionLogStoredRelY[i] == minY)
            {
                firstRowXs[firstRowCount++] = collectionLogStoredRelX[i];
            }
        }
        Arrays.sort(firstRowXs, 0, firstRowCount);
        if (firstRowCount > 0)
        {
            clGridNumCols = firstRowCount;
            clGridStartX = firstRowXs[0];
            if (firstRowCount > 1)
            {
                clGridXStep = firstRowXs[1] - firstRowXs[0];
            }
            else if (children.length > 0 && children[0] != null)
            {
                clGridXStep = children[0].getWidth();
            }
        }

        int minNextY = Integer.MAX_VALUE;
        for (int i = 0; i < children.length; i++)
        {
            if (children[i] != null && children[i].getItemId() > 0)
            {
                int y = collectionLogStoredRelY[i];
                if (y > minY && y < minNextY) minNextY = y;
            }
        }
        if (minNextY != Integer.MAX_VALUE)
        {
            clGridYStep = minNextY - minY;
        }
        else if (children.length > 0 && children[0] != null)
        {
            clGridYStep = children[0].getHeight();
        }
    }

    private void applyCollectionLogFilterAndCompact(Widget[] children)
    {
        int slot = 0;
        for (Widget child : children)
        {
            if (child == null || child.getItemId() <= 0)
            {
                continue;
            }

            if (child.getOpacity() == 0)
            {
                // opacity == 0 → full colour → obtained → hide
                child.setHidden(true);
            }
            else
            {
                // opacity > 0 → grayed-out → not yet obtained → place in next slot
                child.setHidden(false);
                child.setRelativeX(clGridStartX + (slot % clGridNumCols) * clGridXStep);
                child.setRelativeY(clGridStartY + (slot / clGridNumCols) * clGridYStep);
                slot++;
            }
        }
    }

    private void restoreCollectionLogPositions(Widget[] children)
    {
        for (int i = 0; i < children.length; i++)
        {
            Widget child = children[i];
            if (child == null || child.getItemId() <= 0) continue;
            child.setHidden(false);
            if (collectionLogStoredRelX != null && i < collectionLogStoredRelX.length)
            {
                child.setRelativeX(collectionLogStoredRelX[i]);
                child.setRelativeY(collectionLogStoredRelY[i]);
            }
        }
        collectionLogStoredIds = null;
        collectionLogStoredRelX = null;
        collectionLogStoredRelY = null;
    }

    private void restoreCollectionLog()
    {
        collectionLogFilterApplied = false;
        Widget itemContainer = client.getWidget(COLLECTION_LOG_GROUP, COLLECTION_LOG_ITEMS_CONTAINER);
        if (itemContainer != null)
        {
            Widget[] children = itemContainer.getDynamicChildren();
            if (children != null)
            {
                restoreCollectionLogPositions(children);
                return;
            }
        }
        collectionLogStoredIds = null;
        collectionLogStoredRelX = null;
        collectionLogStoredRelY = null;
    }

    @Provides
    TransparentInterfacesConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(TransparentInterfacesConfig.class);
    }
}

