package com.transparentui;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Abstract base class for moveable interface overlays.
 * Handles drag logic, bounds checking, and position management.
 * Subclasses only need to implement interface-specific details.
 */
public abstract class MoveableInterfaceOverlay extends Overlay implements MouseListener
{
    protected final Client client;
    protected final TransparentInterfacesConfig config;
    private final ConfigManager configManager;

    // Drag region and state
    private Rectangle dragRegion;
    private boolean isDragging;
    private Point dragStartMouse;
    private int dragStartOffsetX;
    private int dragStartOffsetY;

    // Position offset from default
    private int offsetX;
    private int offsetY;

    // Base position (captured once when interface opens)
    private int baseRelX = -1;
    private int baseRelY = -1;

    protected MoveableInterfaceOverlay(Client client, TransparentInterfacesConfig config, ConfigManager configManager)
    {
        this.client = client;
        this.config = config;
        this.configManager = configManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    protected abstract boolean isFeatureEnabled();
    protected abstract Widget getInterfaceWindow();
    protected abstract Rectangle getTitleBarDragRegion(Widget interfaceWindow);
    protected abstract String getPositionConfigKey();

    public void onInterfaceLoaded()
    {
        if (!isFeatureEnabled())
        {
            return;
        }
        // Reset base so onBeforeRender captures the freshly-loaded default position
        baseRelX = -1;
        baseRelY = -1;
    }

    public void onBeforeRender()
    {
        if (!isFeatureEnabled())
        {
            return;
        }

        Widget interfaceWindow = getInterfaceWindow();
        if (interfaceWindow == null || interfaceWindow.isHidden())
        {
            return;
        }

        Widget container = getContainer(interfaceWindow);

        if (baseRelX == -1)
        {
            // Capture base at frame start: game has reset widget positions, our offset not yet applied
            loadPosition();
            baseRelX = container.getRelativeX();
            baseRelY = container.getRelativeY();
            clampLoadedOffset(interfaceWindow, container);
        }

        if (offsetX == 0 && offsetY == 0)
        {
            return;
        }

        container.setRelativeX(baseRelX + offsetX);
        container.setRelativeY(baseRelY + offsetY);
    }

    private void clampLoadedOffset(Widget interfaceWindow, Widget container)
    {
        if (offsetX == 0 && offsetY == 0)
        {
            return;
        }

        // Temporarily apply offset so getBounds() reflects the new position
        container.setRelativeX(baseRelX + offsetX);
        container.setRelativeY(baseRelY + offsetY);

        Rectangle bounds = interfaceWindow.getBounds();
        if (bounds == null)
        {
            return;
        }

        int w = client.getCanvasWidth();
        int h = client.getCanvasHeight();
        boolean changed = false;

        if (bounds.x < 0)
        {
            offsetX -= bounds.x;
            changed = true;
        }
        else if (bounds.x + bounds.width > w)
        {
            offsetX -= (bounds.x + bounds.width - w);
            changed = true;
        }

        if (bounds.y < 0)
        {
            offsetY -= bounds.y;
            changed = true;
        }
        else if (bounds.y + bounds.height > h)
        {
            offsetY -= (bounds.y + bounds.height - h);
            changed = true;
        }

        if (changed)
        {
            savePosition();
        }
    }

    private void savePosition()
    {
        configManager.setConfiguration(TransparentInterfacesPlugin.CONFIG_GROUP, getPositionConfigKey() + "OffsetX", offsetX);
        configManager.setConfiguration(TransparentInterfacesPlugin.CONFIG_GROUP, getPositionConfigKey() + "OffsetY", offsetY);
    }

    public void clearSavedPosition()
    {
        configManager.unsetConfiguration(TransparentInterfacesPlugin.CONFIG_GROUP, getPositionConfigKey() + "OffsetX");
        configManager.unsetConfiguration(TransparentInterfacesPlugin.CONFIG_GROUP, getPositionConfigKey() + "OffsetY");
        offsetX = 0;
        offsetY = 0;
    }

    private void loadPosition()
    {
        Integer savedX = configManager.getConfiguration(TransparentInterfacesPlugin.CONFIG_GROUP, getPositionConfigKey() + "OffsetX", Integer.class);
        Integer savedY = configManager.getConfiguration(TransparentInterfacesPlugin.CONFIG_GROUP, getPositionConfigKey() + "OffsetY", Integer.class);
        if (savedX != null) offsetX = savedX;
        if (savedY != null) offsetY = savedY;
    }

    private Widget getContainer(Widget interfaceWindow)
    {
        Widget parent = interfaceWindow.getParent();
        return parent != null ? parent : interfaceWindow;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!isFeatureEnabled())
        {
            if (offsetX != 0 || offsetY != 0)
            {
                resetPosition();
            }
            dragRegion = null;
            return null;
        }

        Widget interfaceWindow = getInterfaceWindow();
        if (interfaceWindow == null || interfaceWindow.isHidden())
        {
            if (baseRelX != -1 && interfaceWindow != null)
            {
                // Reset container to default so the stale offset isn't inherited on next open
                Widget container = getContainer(interfaceWindow);
                container.setRelativeX(baseRelX);
                container.setRelativeY(baseRelY);
            }
            baseRelX = -1;
            baseRelY = -1;
            dragRegion = null;
            return null;
        }

        dragRegion = getTitleBarDragRegion(interfaceWindow);
        return null;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent e)
    {
        if (!isFeatureEnabled() || dragRegion == null || !dragRegion.contains(e.getPoint()))
        {
            return e;
        }

        isDragging = true;
        dragStartMouse = e.getPoint();
        dragStartOffsetX = offsetX;
        dragStartOffsetY = offsetY;
        e.consume();
        return e;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent e)
    {
        if (isDragging)
        {
            isDragging = false;
            dragStartMouse = null;
            savePosition();
            e.consume();
        }
        return e;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent e)
    {
        if (!isDragging || dragStartMouse == null)
        {
            return e;
        }

        Point currentMouse = e.getPoint();
        int newOffsetX = dragStartOffsetX + (currentMouse.x - dragStartMouse.x);
        int newOffsetY = dragStartOffsetY + (currentMouse.y - dragStartMouse.y);

        Widget interfaceWindow = getInterfaceWindow();
        if (interfaceWindow != null && baseRelX != -1)
        {
            Rectangle bounds = interfaceWindow.getBounds();
            if (bounds != null)
            {
                int canvasWidth = client.getCanvasWidth();
                int canvasHeight = client.getCanvasHeight();

                // Clamp X
                int newLeft = baseRelX + newOffsetX;
                if (newLeft < 0)
                {
                    newOffsetX = -baseRelX;
                }
                else if (newLeft + bounds.width > canvasWidth)
                {
                    newOffsetX = canvasWidth - baseRelX - bounds.width;
                }

                // Clamp Y
                int newTop = baseRelY + newOffsetY;
                if (newTop < 0)
                {
                    newOffsetY = -baseRelY;
                }
                else if (newTop + bounds.height > canvasHeight)
                {
                    newOffsetY = canvasHeight - baseRelY - bounds.height;
                }
            }
        }

        offsetX = newOffsetX;
        offsetY = newOffsetY;
        e.consume();
        return e;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent e) { return e; }
    @Override
    public MouseEvent mouseEntered(MouseEvent e) { return e; }
    @Override
    public MouseEvent mouseExited(MouseEvent e) { return e; }
    @Override
    public MouseEvent mouseMoved(MouseEvent e) { return e; }

    public void resetPosition()
    {
        if (baseRelX != -1)
        {
            Widget interfaceWindow = getInterfaceWindow();
            if (interfaceWindow != null)
            {
                Widget container = getContainer(interfaceWindow);
                container.setRelativeX(baseRelX);
                container.setRelativeY(baseRelY);
            }
        }
        offsetX = 0;
        offsetY = 0;
        baseRelX = -1;
        baseRelY = -1;
        isDragging = false;
        dragStartMouse = null;
        dragRegion = null;
    }
}

