package com.transparentui;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class BankHoverOverlay extends Overlay
{
    private static final int ITEM_CONTAINER_MIN_CHILDREN = 100;
    private static final BasicStroke HIGHLIGHT_STROKE = new BasicStroke(2);

    private final Client client;
    private final TransparentInterfacesConfig config;

    // Cached child ID of the item container; -1 means not yet found or bank is closed.
    private int itemContainerChildId = -1;

    @Inject
    BankHoverOverlay(Client client, TransparentInterfacesConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    @SuppressWarnings("deprecation")
    public Dimension render(Graphics2D graphics)
    {
        if (!config.enableBankHoverHighlight())
        {
            return null;
        }

        Widget bankWindow = client.getWidget(InterfaceID.BANK, 0);
        if (bankWindow == null || bankWindow.isHidden())
        {
            itemContainerChildId = -1;
            return null;
        }

        if (itemContainerChildId == -1)
        {
            itemContainerChildId = findItemContainerChildId();
        }

        Widget itemContainer = itemContainerChildId == -1
            ? null
            : client.getWidget(InterfaceID.BANK, itemContainerChildId);

        if (itemContainer == null || itemContainer.isHidden())
        {
            itemContainerChildId = -1;
            return null;
        }

        Widget[] children = itemContainer.getDynamicChildren();
        if (children == null || children.length == 0)
        {
            return null;
        }

        net.runelite.api.Point mouseCanvas = client.getMouseCanvasPosition();
        Point mouse = new Point(mouseCanvas.getX(), mouseCanvas.getY());

        net.runelite.api.Point containerLocation = itemContainer.getCanvasLocation();
        if (containerLocation == null)
        {
            return null;
        }

        Rectangle containerBounds = new Rectangle(
            containerLocation.getX(),
            containerLocation.getY(),
            itemContainer.getWidth(),
            itemContainer.getHeight()
        );

        if (!containerBounds.contains(mouse))
        {
            return null;
        }

        int scrollY = itemContainer.getScrollY();
        Color highlightColor = config.bankHoverHighlightColor();
        int alpha = config.bankHoverHighlightAlpha();

        Composite originalComposite = graphics.getComposite();
        Stroke originalStroke = graphics.getStroke();

        Rectangle bounds = new Rectangle();

        for (Widget child : children)
        {
            if (child == null || child.isHidden() || child.getItemId() == -1)
            {
                continue;
            }

            bounds.setBounds(
                containerLocation.getX() + child.getRelativeX(),
                containerLocation.getY() + child.getRelativeY() - scrollY,
                child.getWidth(),
                child.getHeight()
            );

            if (bounds.isEmpty() || !bounds.contains(mouse))
            {
                continue;
            }

            if (alpha > 0)
            {
                graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha / 255.0f));
                graphics.setColor(highlightColor);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                graphics.setComposite(originalComposite);
            }

            graphics.setStroke(HIGHLIGHT_STROKE);
            graphics.setColor(highlightColor);
            graphics.drawRect(bounds.x + 1, bounds.y + 1, Math.max(0, bounds.width - 2), Math.max(0, bounds.height - 2));
            graphics.setStroke(originalStroke);

            break;
        }

        return null;
    }

    private int findItemContainerChildId()
    {
        for (int childId = 0; childId <= 25; childId++)
        {
            Widget candidate = client.getWidget(InterfaceID.BANK, childId);
            if (candidate == null)
            {
                continue;
            }

            Widget[] dynamic = candidate.getDynamicChildren();
            if (dynamic != null && dynamic.length >= ITEM_CONTAINER_MIN_CHILDREN)
            {
                return childId;
            }
        }

        return -1;
    }
}

